CREATE FUNCTION public.prepare_patient_status_notice(_request uuid,_channel text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ride_requests;t public.trips;s text;stage text;ws uuid;version text;key text;eventid uuid;person text;dest text; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='communication_event_preparation' AND enabled) THEN RAISE EXCEPTION 'Communication preparation is off'; END IF;
 IF _channel NOT IN ('in_app','email') OR NOT public.patient_request_access(_request) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Notice unavailable'; END IF;
 SELECT * INTO r FROM public.ride_requests WHERE id=_request; SELECT * INTO t FROM public.trips WHERE ride_request_id=r.id ORDER BY created_at DESC LIMIT 1;ws:=coalesce(r.patient_workspace_id,r.workspace_id);
 IF r.workspace_id<>ws AND NOT EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND ((c.workspace_a=r.workspace_id AND c.workspace_b=ws) OR (c.workspace_b=r.workspace_id AND c.workspace_a=ws))) THEN RAISE EXCEPTION 'Notice unavailable'; END IF;
 s:=coalesce(t.status,r.lifecycle_state,r.status); stage:=CASE WHEN s IN ('canceled','cancelled') THEN 'Canceled' WHEN s='completed' THEN 'Completed' WHEN s IN ('scheduled','dispatched','driver_assigned') THEN 'Added to Dispatch Schedule' WHEN s IN ('approved','confirmed','accepted','reserved','assigned','in_progress') THEN 'Approved' WHEN s IN ('pending','received','new') THEN 'Pending' END;
 IF stage IS NULL THEN RAISE EXCEPTION 'Notice unavailable'; END IF;
 IF stage NOT IN ('Canceled','Completed') AND EXISTS(SELECT 1 FROM public.trip_invoice_documents i WHERE i.request_id=r.id AND i.status IN ('ready','sent','payment_pending') AND public.trip_invoice_access(i.id,false) AND (public.get_trip_invoice_snapshot(i.id)->>'balanceCents')::numeric>0) THEN stage:='Waiting on Payment'; END IF;
 version:=md5(concat_ws('|',t.updated_at::text,t.status,r.lifecycle_state,r.last_updated_at::text));key:=concat_ws(':',auth.uid(),coalesce(t.id,r.id),version,stage,_channel);
 SELECT mfn_id INTO person FROM public.user_profiles WHERE user_id=auth.uid();SELECT encode(extensions.digest(lower(email),'sha256'),'hex') INTO dest FROM auth.users WHERE id=auth.uid();
 INSERT INTO public.notifications(user_id,type,title,body,ride_request_id,communication) VALUES(auth.uid(),'customer_trip_status',stage,r.mfn_id,r.id,jsonb_build_object('reference','MFN-C-'||upper(replace(gen_random_uuid()::text,'-','')),'workspaceId',ws,'recipientId',auth.uid(),'tripId',t.id,'requestId',r.id,'category','trip_status','templateVersion','customer-update-2026-11-08','channel',_channel,'state','prepared','reason','delivery_off','dedupeKey',key,'version',version,'scheduledAt',NULL,'timezone',t.communication_timezone,'policyBasis','required_active_trip_operation','deliveryEnabled',false,'createdBy',auth.uid(),'personMfnId',person,'destinationHash',dest)) ON CONFLICT DO NOTHING RETURNING id INTO eventid;
 IF eventid IS NULL THEN SELECT id INTO eventid FROM public.notifications WHERE communication->>'dedupeKey'=key; END IF;RETURN eventid; END $$;
REVOKE ALL ON FUNCTION public.prepare_patient_status_notice(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.prepare_patient_status_notice(uuid,text) TO authenticated;
CREATE FUNCTION public.invalidate_prepared_communication_destination() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n public.notifications; BEGIN
 IF NEW.email IS NOT DISTINCT FROM OLD.email THEN RETURN NEW; END IF;
 FOR n IN SELECT * FROM public.notifications WHERE user_id=NEW.id AND communication IS NOT NULL AND communication->>'channel'='email' AND communication->>'state' IN ('prepared','suppressed','not_configured','failed') LOOP
 INSERT INTO public.notifications(user_id,type,title,body,ride_request_id,communication) VALUES(n.user_id,'communication_cancellation','Prepared email destination changed',NULL,n.ride_request_id,n.communication||jsonb_build_object('reference','MFN-C-'||upper(replace(gen_random_uuid()::text,'-','')),'state','canceled','reason','authoritative_email_changed','dedupeKey',n.communication->>'dedupeKey'||':destination_changed','canceledAt',now(),'supersedesId',n.id)) ON CONFLICT DO NOTHING;
 END LOOP; RETURN NEW; END $$;
CREATE TRIGGER communication_destination_confirmed_change AFTER UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.invalidate_prepared_communication_destination();
